use serde_json::Value;

pub fn solve(input: Value) -> Value {
    match input {
        Value::Array(arr) if arr.is_empty() => Value::Array(vec![]),
        Value::Array(arr) => {
            let mut prefix_sums = Vec::with_capacity(arr.len());
            let mut current_sum = 0;
            for item in arr {
                if let Value::Number(num) = item {
                    if let Some(n) = num.as_i64() {
                        current_sum += n;
                        prefix_sums.push(serde_json::Number::from(current_sum));
                    }
                }
            }
            Value::Array(prefix_sums)
        },
        _ => Value::Array(vec![]),
    }
}
